import java.util.ArrayList;
import java.util.List;

public class DeliveryFormatter {
    private final CapabilityRegistry registry;

    public DeliveryFormatter(CapabilityRegistry registry) {
        this.registry = registry;
    }

    public List<String> formatForEndpoint(Endpoint endpoint, List<String> codecs) {
        List<String> offer = new ArrayList<>(codecs.stream()
            .filter(codec -> registry.supports(endpoint, codec))
            .toList());
        offer.sort((a, b) -> endpoint.rank(a) - endpoint.rank(b));
        return offer;
    }
}
